"use client"

import { createColumnHelper } from "@tanstack/react-table"
import { EllipsisIcon, PencilIcon } from "lucide-react"
import { useCallback, useRef } from "react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
  DataTableColumnHeader,
  type DataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import type { ResponsiveColumn } from "@/components/blocks/openlmis/data-table/responsive-columns"
import { StatusBadge } from "@/components/openlmis/status-badge"

import type { Program } from "@/components/openlmis/programs-page/program-form"

/** The columns the View menu lists; the program's name is left out, so it always shows. */
export const PROGRAM_HIDEABLE_COLUMNS: (ResponsiveColumn & {
  label: string
})[] = [
  { id: "code", label: "Code", hideBelow: "md" },
  { id: "active", label: "Status", hideBelow: "sm" },
]

export const PROGRAM_SORT_FIELDS = ["name", "code", "active"] as const

export type ProgramSortField = (typeof PROGRAM_SORT_FIELDS)[number]

const columnHelper = createColumnHelper<DataTableFeatures, Program>()

export function createProgramColumns(onEdit: (id: string) => void) {
  return columnHelper.columns([
    columnHelper.accessor("name", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Program" />
      ),
      cell: ({ getValue }) =>
        getValue() ? (
          <span className="flex">
            <span className="min-w-0 truncate font-medium" dir="auto">
              {getValue()}
            </span>
          </span>
        ) : (
          <span className="text-muted-foreground">-</span>
        ),
    }),
    columnHelper.accessor("code", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Code" />
      ),
      cell: ({ getValue }) => (
        <span className="flex">
          <span className="min-w-0 truncate" dir="ltr">
            {getValue()}
          </span>
        </span>
      ),
      meta: { className: "@xl/table:w-1/4" },
    }),
    columnHelper.accessor("active", {
      header: ({ column }) => (
        <DataTableColumnHeader column={column} title="Status" />
      ),
      cell: ({ getValue }) =>
        getValue() ? (
          <StatusBadge tone="success">Active</StatusBadge>
        ) : (
          <StatusBadge tone="destructive">Inactive</StatusBadge>
        ),
      meta: { className: "w-32" },
    }),
    columnHelper.display({
      id: "actions",
      header: () => <span className="sr-only">Actions</span>,
      cell: ({ row }) => (
        <ProgramActions onEdit={onEdit} program={row.original} />
      ),
      meta: { className: "w-16" },
    }),
  ])
}

/** Keeps a closing menu from taking focus back to its trigger when an item opened a dialog, which then owns focus. */
function useMenuOpensDialog() {
  const opened = useRef(false)

  const onOpenChange = useCallback((open: boolean) => {
    if (open) opened.current = false
  }, [])
  const finalFocus = useCallback(() => !opened.current, [])
  const opensDialog = useCallback(
    (open: () => void) => () => {
      opened.current = true
      open()
    },
    []
  )

  return { onOpenChange, finalFocus, opensDialog }
}

function ProgramActions({
  program,
  onEdit,
}: {
  program: Program
  onEdit: (id: string) => void
}) {
  const menu = useMenuOpensDialog()

  return (
    <div className="flex justify-end">
      <DropdownMenu onOpenChange={menu.onOpenChange}>
        <DropdownMenuTrigger
          render={
            <Button
              aria-label={`Actions For ${program.name || program.code}`}
              size="icon-sm"
              variant="ghost"
            />
          }
        >
          <EllipsisIcon />
        </DropdownMenuTrigger>
        <DropdownMenuContent
          align="end"
          className="w-auto"
          finalFocus={menu.finalFocus}
        >
          <DropdownMenuGroup>
            <DropdownMenuItem
              onClick={menu.opensDialog(() => onEdit(program.id))}
            >
              <PencilIcon />
              Edit
            </DropdownMenuItem>
          </DropdownMenuGroup>
        </DropdownMenuContent>
      </DropdownMenu>
    </div>
  )
}

"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { type ReactNode, useEffect, useMemo, useRef } from "react"

import { FieldGroup } from "@/components/ui/field"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogError,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogLoadError,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  FieldSkeleton,
  SkeletonLine,
} from "@/components/openlmis/form-fields/form-fields"

import {
  EMPTY_PROGRAM_FORM,
  type Program,
  type ProgramFormValues,
  programFormSchema,
  toProgramFormValues,
} from "@/components/openlmis/programs-page/program-form"

type SwitchName = {
  [K in keyof ProgramFormValues]: ProgramFormValues[K] extends boolean
    ? K
    : never
}[keyof ProgramFormValues]

const SWITCHES: readonly {
  name: SwitchName
  label: string
  description?: string
}[] = [
  { name: "active", label: "Active" },
  {
    name: "showNonFullSupplyTab",
    label: "Display Non-Full Supply Tab",
    description:
      "Enable the Non-Full Supply tab for this program's requisition form.",
  },
  {
    name: "periodsSkippable",
    label: "Allow Skipping Periods",
    description: "Enable skipping periods for this program's requisition form.",
  },
  {
    name: "skipAuthorization",
    label: "Skip Authorization Step",
    description:
      "When selected, requisitions from this program will not go through authorization.",
  },
  {
    name: "enableDatePhysicalStockCountCompleted",
    label: "Enable Field For Date Physical Stock Count Completed",
    description:
      "Require users to enter this date when a requisition is submitted; the date can be edited when a requisition is authorized.",
  },
]

const NO_CODES: readonly string[] = []

/** `new` to add a program, or the id of the program to edit. */
export type ProgramFormDialogTarget = "new" | (string & {})

type ProgramFormDialogProps = {
  /** Opens the dialog while set. */
  target: ProgramFormDialogTarget | undefined
  /** The program being edited; a skeleton shows until it is set. */
  program?: Program | undefined
  /** Codes already taken, refused for a new program; include any the server refused. */
  takenCodes?: readonly string[]
  /** The program to edit no longer exists. */
  notFound?: boolean
  /** Loading the program failed; shows the error with Try Again. */
  onRetry?: (() => void) | undefined
  /** Called with the values; save them, then clear `target` to close. */
  onSubmit: (values: ProgramFormValues, program: Program | undefined) => void
  /** Keeps the dialog open and shows a spinner while the program is saved. */
  pending?: boolean
  /** Shown above the fields, e.g. why the save failed. */
  error?: ReactNode
  onClose: () => void
}

export function ProgramFormDialog({
  target,
  program,
  takenCodes = NO_CODES,
  notFound = false,
  onRetry,
  onSubmit,
  pending = false,
  error,
  onClose,
}: ProgramFormDialogProps) {
  const { shown, dialogProps } = useDialogTarget(target, onClose)
  const isNew = shown === "new"
  const title = isNew ? "Add Program" : "Edit Program"
  const submitLabel = isNew ? "Add Program" : "Save"

  return (
    <FormDialog {...dialogProps(pending)}>
      {shown &&
        (isNew ? (
          <ProgramForm
            error={error}
            key="new"
            onSubmit={onSubmit}
            pending={pending}
            takenCodes={takenCodes}
          />
        ) : notFound ? (
          <>
            <FormDialogHeader>
              <FormDialogTitle>{title}</FormDialogTitle>
              <FormDialogDescription>
                This program no longer exists.
              </FormDialogDescription>
            </FormDialogHeader>
            <FormDialogFooter>
              <FormDialogCancel>Close</FormDialogCancel>
            </FormDialogFooter>
          </>
        ) : onRetry ? (
          <FormDialogLoadError
            errorTitle="Could Not Load Program"
            onRetry={onRetry}
            title={title}
          />
        ) : program === undefined ? (
          <ProgramFormSkeleton submitLabel={submitLabel} title={title} />
        ) : (
          <ProgramForm
            error={error}
            // Keyed, so opening another program starts a fresh form.
            key={program.id}
            onSubmit={onSubmit}
            pending={pending}
            program={program}
            takenCodes={takenCodes}
          />
        ))}
    </FormDialog>
  )
}

type ProgramFormProps = Pick<
  ProgramFormDialogProps,
  "program" | "onSubmit" | "error"
> & {
  takenCodes: readonly string[]
  pending: boolean
}

function ProgramForm({
  program,
  takenCodes,
  onSubmit,
  pending,
  error,
}: ProgramFormProps) {
  // Keyed on the codes themselves, so an equal array passed inline does not rebuild or re-check.
  // A saved program's code is locked, so only a new one is checked against the others.
  const codesKey = program ? "[]" : JSON.stringify(takenCodes)
  const schema = useMemo(
    () => programFormSchema(JSON.parse(codesKey) as string[]),
    [codesKey]
  )
  const checkedKey = useRef(codesKey)

  const form = useAppForm({
    defaultValues: program ? toProgramFormValues(program) : EMPTY_PROGRAM_FORM,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: schema },
    onSubmit: ({ value }) => onSubmit(value, program),
  })

  // A code the server just refused shows its error at once, without another submit.
  useEffect(() => {
    if (checkedKey.current === codesKey) return
    checkedKey.current = codesKey
    void form.validate("change")
  }, [codesKey, form])

  return (
    <FormDialogForm onSubmit={form.handleSubmit}>
      <FormDialogHeader>
        <FormDialogTitle>
          {program ? "Edit Program" : "Add Program"}
        </FormDialogTitle>
        <FormDialogDescription>
          Changes are effective immediately.
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          {error && (
            <FormDialogError
              description={error}
              title="Could Not Save Program"
            />
          )}
          <form.AppField name="code">
            {(field) => (
              <field.TextField
                autoComplete="off"
                description={
                  program
                    ? "The code can't be changed once the program exists."
                    : undefined
                }
                dir="ltr"
                disabled={Boolean(program)}
                label="Program Code"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="name">
            {(field) => (
              <field.TextField
                autoComplete="off"
                label="Program Name"
                required
              />
            )}
          </form.AppField>
          <form.AppField name="description">
            {(field) => <field.TextareaField label="Description" />}
          </form.AppField>
          {SWITCHES.map((setting) => (
            <form.AppField key={setting.name} name={setting.name}>
              {(field) => (
                <field.SwitchField
                  description={setting.description}
                  label={setting.label}
                />
              )}
            </form.AppField>
          ))}
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel disabled={pending} />
        <FormDialogSubmit pending={pending}>
          {program ? "Save" : "Add Program"}
        </FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

/** A switch row whose value is still loading, laid out like `SwitchField`. */
function SwitchSkeleton() {
  return (
    <div
      aria-hidden
      className="flex min-h-8 items-center justify-between gap-3"
    >
      <SkeletonLine width="short" />
      {/* A plain element, since Skeleton owns its corner radius and a switch is round. */}
      <div className="h-4.5 w-8 shrink-0 animate-pulse rounded-full bg-muted" />
    </div>
  )
}

/** Laid out like the form, so nothing moves when the program arrives. */
function ProgramFormSkeleton({
  title,
  submitLabel,
}: {
  title: string
  submitLabel: string
}) {
  return (
    <>
      <FormDialogHeader>
        <FormDialogTitle>{title}</FormDialogTitle>
        <SkeletonLine />
      </FormDialogHeader>
      <FormDialogBody>
        <div aria-busy>
          <FieldGroup>
            <FieldSkeleton label="Program Code" required />
            <FieldSkeleton label="Program Name" required />
            <FieldSkeleton label="Description" />
            {SWITCHES.map((setting) => (
              <SwitchSkeleton key={setting.name} />
            ))}
          </FieldGroup>
        </div>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit disabled>{submitLabel}</FormDialogSubmit>
      </FormDialogFooter>
    </>
  )
}

import { z } from "zod"

/** A program as the form reads and writes it; map your API's program onto it. */
export type Program = {
  id: string
  code: string
  name: string | null
  description: string | null
  active: boolean
  showNonFullSupplyTab: boolean
  periodsSkippable: boolean
  skipAuthorization: boolean
  enableDatePhysicalStockCountCompleted: boolean
}

const withoutSpaces = (code: string) => code.replace(/\s/g, "")

/** Refuses a code already taken, ignoring spaces as the server does. */
export function programFormSchema(takenCodes: readonly string[]) {
  const taken = new Set(takenCodes.map(withoutSpaces))
  return z.object({
    code: z
      .string()
      .trim()
      .min(1, "Enter a code.")
      .refine(
        (code) => !taken.has(withoutSpaces(code)),
        "Another program already has this code."
      ),
    name: z.string().trim().min(1, "Enter a name."),
    description: z.string(),
    active: z.boolean(),
    showNonFullSupplyTab: z.boolean(),
    periodsSkippable: z.boolean(),
    skipAuthorization: z.boolean(),
    enableDatePhysicalStockCountCompleted: z.boolean(),
  })
}

export type ProgramFormValues = z.infer<ReturnType<typeof programFormSchema>>

export const EMPTY_PROGRAM_FORM: ProgramFormValues = {
  code: "",
  name: "",
  description: "",
  active: true,
  showNonFullSupplyTab: false,
  periodsSkippable: false,
  skipAuthorization: false,
  enableDatePhysicalStockCountCompleted: false,
}

export function toProgramFormValues(program: Program): ProgramFormValues {
  return {
    code: program.code,
    name: program.name ?? "",
    description: program.description ?? "",
    active: program.active,
    showNonFullSupplyTab: program.showNonFullSupplyTab,
    periodsSkippable: program.periodsSkippable,
    skipAuthorization: program.skipAuthorization,
    enableDatePhysicalStockCountCompleted:
      program.enableDatePhysicalStockCountCompleted,
  }
}

/** The saved program with the form's values; a saved program keeps its code. */
export function toProgram(
  values: ProgramFormValues,
  saved?: Program
): Omit<Program, "id"> {
  return {
    ...saved,
    code: saved?.code ?? values.code.trim(),
    name: values.name.trim(),
    description: values.description.trim() || null,
    active: values.active,
    showNonFullSupplyTab: values.showNonFullSupplyTab,
    periodsSkippable: values.periodsSkippable,
    skipAuthorization: values.skipAuthorization,
    enableDatePhysicalStockCountCompleted:
      values.enableDatePhysicalStockCountCompleted,
  }
}

"use client"

import {
  type ColumnVisibilityState,
  functionalUpdate,
  type PaginationState,
  type SortingState,
  useTable,
} from "@tanstack/react-table"
import { LayersIcon, PlusIcon } from "lucide-react"
import { useCallback, useMemo, useRef, useState } from "react"

import { Button } from "@/components/ui/button"
import {
  DataTable,
  DataTableEmpty,
  DataTablePagination,
  dataTableFeatures,
} from "@/components/blocks/openlmis/data-table/data-table"
import {
  useColumnVisibility,
  useContainerSize,
} from "@/components/blocks/openlmis/data-table/responsive-columns"
import {
  ListToolbar,
  ListToolbarEnd,
} from "@/components/blocks/openlmis/list-toolbar"
import {
  Workspace,
  WorkspaceContent,
  WorkspaceDescription,
  WorkspaceHeader,
  WorkspaceHeading,
  WorkspaceIcon,
  WorkspaceTitle,
} from "@/components/blocks/openlmis/workspace"
import { Callout } from "@/components/openlmis/callout"
import { ColumnViewOptions } from "@/components/openlmis/column-view-options"

import { MOCK_PROGRAMS } from "@/components/openlmis/programs-page/mock-programs"
import {
  createProgramColumns,
  PROGRAM_HIDEABLE_COLUMNS,
  type ProgramSortField,
} from "@/components/openlmis/programs-page/program-columns"
import {
  type Program,
  type ProgramFormValues,
  toProgram,
} from "@/components/openlmis/programs-page/program-form"
import {
  ProgramFormDialog,
  type ProgramFormDialogTarget,
} from "@/components/openlmis/programs-page/program-form-dialog"

const DEFAULT_SORT = { id: "name", desc: false }
const DEFAULT_SORTING: SortingState = [DEFAULT_SORT]

const getRowId = (program: Program) => program.id

const byName = (a: Program, b: Program) =>
  (a.name ?? "").localeCompare(b.name ?? "", undefined, {
    sensitivity: "base",
  })

const COMPARE: Record<ProgramSortField, (a: Program, b: Program) => number> = {
  name: byName,
  code: (a, b) => a.code.localeCompare(b.code),
  active: (a, b) => Number(b.active) - Number(a.active),
}

type Notice = { title: string; description: string }

/** The programs list screen; mount it from any route, e.g. the `page.tsx` this template ships. */
export function ProgramsPage() {
  const [programs, setPrograms] = useState(MOCK_PROGRAMS)
  const [sorting, setSorting] = useState(DEFAULT_SORTING)
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: 10,
  })
  const [target, setTarget] = useState<ProgramFormDialogTarget>()
  const [notice, setNotice] = useState<Notice>()
  const nextId = useRef(MOCK_PROGRAMS.length + 1)
  const [measureContent, contentSize] = useContainerSize<HTMLDivElement>()
  // Kept for the visit only; store it (e.g. in localStorage) to remember it across visits.
  const columnChoices = useState<ColumnVisibilityState>({})
  const columnView = useColumnVisibility(
    PROGRAM_HIDEABLE_COLUMNS,
    columnChoices,
    contentSize
  )

  // Stable, so the columns built from it keep their identity between renders.
  const openDialog = useCallback((next: ProgramFormDialogTarget) => {
    setNotice(undefined)
    setTarget(next)
  }, [])
  const columns = useMemo(() => createProgramColumns(openDialog), [openDialog])

  // Every program is in memory, so sorting and paging happen here.
  const sorted = useMemo(() => {
    const [sort = DEFAULT_SORT] = sorting
    const compare = COMPARE[sort.id as ProgramSortField]
    // oxlint-disable-next-line unicorn/no-array-sort -- sorts a fresh copy; toSorted needs the ES2023 lib
    return [...programs].sort(
      (a, b) => (sort.desc ? -compare(a, b) : compare(a, b)) || byName(a, b)
    )
  }, [programs, sorting])
  const lastPage = Math.max(
    0,
    Math.ceil(sorted.length / pagination.pageSize) - 1
  )
  const page = useMemo(
    () => ({
      ...pagination,
      pageIndex: Math.min(pagination.pageIndex, lastPage),
    }),
    [pagination, lastPage]
  )
  const data = useMemo(
    () =>
      sorted.slice(
        page.pageIndex * page.pageSize,
        (page.pageIndex + 1) * page.pageSize
      ),
    [sorted, page]
  )

  const table = useTable({
    features: dataTableFeatures,
    columns,
    data,
    getRowId,
    rowCount: sorted.length,
    manualPagination: true,
    manualSorting: true,
    enableSortingRemoval: false,
    state: {
      pagination: page,
      sorting,
      columnVisibility: columnView.visibility,
    },
    onPaginationChange: (updater) =>
      setPagination(functionalUpdate(updater, page)),
    onSortingChange: (updater) => {
      setSorting(functionalUpdate(updater, sorting))
      setPagination((current) => ({ ...current, pageIndex: 0 }))
    },
  })

  const editing = programs.find((program) => program.id === target)

  const save = (values: ProgramFormValues, saved: Program | undefined) => {
    const program = toProgram(values, saved)
    if (saved) {
      setPrograms((current) =>
        current.map((item) =>
          item.id === saved.id ? { ...program, id: saved.id } : item
        )
      )
      setNotice({
        title: "Program Saved",
        description: `Changes to ${program.name} are saved.`,
      })
    } else {
      const id = `program-${nextId.current++}`
      setPrograms((current) => [...current, { ...program, id }])
      setNotice({
        title: "Program Created",
        description: `${program.name} is ready to use.`,
      })
    }
    setTarget(undefined)
  }

  return (
    <Workspace>
      <WorkspaceHeader>
        <WorkspaceHeading>
          <WorkspaceIcon>
            <LayersIcon />
          </WorkspaceIcon>
          <WorkspaceTitle>Programs</WorkspaceTitle>
          <WorkspaceDescription>
            Lines of supply that products, requisitions, stock and roles are set
            up for.
          </WorkspaceDescription>
        </WorkspaceHeading>
      </WorkspaceHeader>
      <WorkspaceContent>
        {/* Measured, because the room for columns depends on a sidebar as well as the window. */}
        <div
          className="flex flex-col gap-4 @4xl/main:gap-6"
          ref={measureContent}
        >
          {notice && (
            <Callout title={notice.title} tone="success">
              {notice.description}
            </Callout>
          )}
          <ListToolbar>
            <ListToolbarEnd>
              <ColumnViewOptions
                columns={PROGRAM_HIDEABLE_COLUMNS}
                onReset={columnView.onReset}
                onVisibilityChange={columnView.onVisibilityChange}
                visibility={columnView.visibility}
              />
            </ListToolbarEnd>
            <div className="w-full @2xl/toolbar:w-auto">
              <Button className="w-full" onClick={() => openDialog("new")}>
                <PlusIcon data-icon="inline-start" />
                Add Program
              </Button>
            </div>
          </ListToolbar>
          <DataTable
            empty={
              <DataTableEmpty
                action={
                  <Button onClick={() => openDialog("new")}>
                    <PlusIcon data-icon="inline-start" />
                    Add Program
                  </Button>
                }
                description="Programs you add appear here."
                icon={<LayersIcon />}
                title="No Programs Yet"
              />
            }
            footer={sorted.length > 0 && <DataTablePagination table={table} />}
            table={table}
          />
        </div>
      </WorkspaceContent>
      <ProgramFormDialog
        onClose={() => setTarget(undefined)}
        onSubmit={save}
        program={editing}
        takenCodes={programs.map((program) => program.code)}
        target={target}
      />
    </Workspace>
  )
}

import { ProgramsPage } from "@/components/openlmis/programs-page/programs-page"

// A Next.js App Router route; in any other React app, render ProgramsPage from your own route.
export default function Page() {
  return <ProgramsPage />
}
